// 单链表按位序插入，在第i个位置前插入元素e
Status ListInsert(LinkList *L, int i, ElemType e) {
    LinkList p = *L; int j = 0;
    while(p && j < i-1) { p = p->next; j++; }
    if(!p || j > i-1) return ERROR;
    LNode *s = (LNode*)malloc(sizeof(LNode));
    s->data = e; s->next = p->next;
    p->next = s;
    return OK;
}

// 合并两个升序顺序表，结果存入C并保持升序
void MergeSqList(SqList A, SqList B, SqList *C) {
    int i=0, j=0, k=0;
    while(i<A.length && j<B.length) {
        if(A.data[i] <= B.data[j])
            C->data[k++] = A.data[i++];
        else
            C->data[k++] = B.data[j++];
    }
    while(i < A.length) C->data[k++] = A.data[i++];
    while(j < B.length) C->data[k++] = B.data[j++];
    C->length = k;
}

// 删除双向链表中的节点p，返回被删元素值
ElemType DuListDelete(DuLNode *p) {
    ElemType e = p->data;
    if(p->prior != NULL) p->prior->next = p->next;
    if(p->next != NULL) p->next->prior = p->prior;
    free(p);
    return e;
}

// 有序顺序表合并
void MergeList_Sq(SqList A, SqList B, SqList *C) {
    int i=0,j=0,k=0;
    while(i<A.length && j<B.length){
        if(A.data[i]<=B.data[j])
            C->data[k++]=A.data[i++];
        else
            C->data[k++]=B.data[j++];
    }
    while(i<A.length) C->data[k++]=A.data[i++];
    while(j<B.length) C->data[k++]=B.data[j++];
    C->length=k;
}

// 顺序栈入栈，栈满则扩容
Status Push(SqStack *S, ElemType e) {
    if(S->top - S->base >= S->stacksize) {
        S->base = (ElemType*)realloc(S->base,
            (S->stacksize+STACKINCREMENT)*sizeof(ElemType));
        if(!S->base) return OVERFLOW;
        S->top = S->base + S->stacksize;
        S->stacksize += STACKINCREMENT;
    }
    *S->top++ = e;
    return OK;
}

// 顺序栈初始化
Status InitStack(SqStack S) {
    S->base = (ElemType)malloc(STACK_INIT_SIZE * sizeof(ElemType));
    if(!S->base) exit(OVERFLOW);
    S->top = S->base;
    S->stacksize = STACK_INIT_SIZE;
    return OK;
}

// 顺序栈入栈
Status Push(SqStack S, ElemType e) {
    if(S->top - S->base >= S->stacksize) {
        S->base = (ElemType)realloc(S->base, (S->stacksize + STACKINCREMENT) * sizeof(ElemType));
        if(!S->base) exit(OVERFLOW);
        S->top = S->base + S->stacksize;
        S->stacksize += STACKINCREMENT;
    }
    *(S->top++) = e;
    return OK;
}

// 链栈入栈（头插法）
Status LinkPush(LinkStack *S, ElemType e) {
    SNode p = (SNode)malloc(sizeof(SNode));
    if(!p) return ERROR;
    p->data = e;
    p->next = *S;
    *S = p;
    return OK;
}

// 用两个栈实现队列：入队直接压栈1，出队时栈2空则将栈1全部倒入栈2再弹出
void push(int x) { stack1.push(x); }
int pop() {
    if(stack2.empty())
        while(!stack1.empty())
            { stack2.push(stack1.top()); stack1.pop(); }
    int res = stack2.top(); stack2.pop();
    return res;
}

// 块链存储节点定义
#define CHUNKSIZE 80
typedef struct Chunk {
    char ch[CHUNKSIZE];
    struct Chunk *next;
} Chunk;
typedef struct {
    Chunk *head, tail;
    int curlen;
} LString;

// 求广义表深度递归算法
int GListDepth(GList L) {
    if(!L) return 1;
    if(L->tag == ATOM) return 0;
    int max = 0;
    for(GList p = L; p; p = p->ptr.tp) {
        int dep = GListDepth(p->ptr.hp);
        if(dep > max) max = dep;
    }
    return max + 1;
}

// 求广义表深度递归算法
int GListDepth(GList L) {
    if(!L) return 1;
    if(L->tag==ATOM) return 0;
    int max=0;
    for(GList p=L->ptr.hp; p; p=p->tp){
        int d=GListDepth(p);
        if(d>max) max=d;
    }
    return max+1;
}

// 先序遍历递归算法
void PreOrder(BiTree T) {
    if(T) {
        visit(T->data);
        PreOrder(T->lchild);
        PreOrder(T->rchild);
    }
}

// 层序遍历
void LevelOrder(BiTree T) {
    SqQueue Q; InitQueue(&Q);
    BiTree p;
    EnQueue(&Q, T);
    while(!QueueEmpty(Q)) {
        DeQueue(&Q, &p);
        visit(p->data);
        if(p->lchild) EnQueue(&Q, p->lchild);
        if(p->rchild) EnQueue(&Q, p->rchild);
    }
}

// 中序遍历非递归算法
void InOrderNonRec(BiTree T) {
    SqStack S; InitStack(&S);
    BiTree p = T;
    while(p || !StackEmpty(S)) {
        if(p) { Push(&S, p); p = p->lchild; }
        else { Pop(&S, &p); visit(p->data); p = p->rchild; }
    }
}

// 二叉树先序遍历递归实现
void PreOrder(BiTree T) {
    if(T) {
        visit(T->data);
        PreOrder(T->lchild);
        PreOrder(T->rchild);
    }
}

// 中序非递归遍历
void InOrderNonRec(BiTree T) {
    SqStack S; InitStack(&S);
    BiTree p=T;
    while(p||!StackEmpty(S)){
        if(p){ Push(&S,p); p=p->lchild; }
        else{ Pop(&S,&p); visit(p->data); p=p->rchild; }
    }
}

// BFS遍历连通图
void BFS(Graph G, int v) {
    visited[v] = TRUE; visit(v);
    EnQueue(&Q, v);
    while(!QueueEmpty(Q)) {
        DeQueue(&Q, &u);
        for(int w = FirstAdjVex(G, u); w >= 0; w = NextAdjVex(G, u, w))
            if(!visited[w]) { visited[w]=TRUE; visit(w); EnQueue(&Q, w); }
    }
}

// 折半查找实现
int SearchBin(SSTable ST, KeyType key){
    int low=1,high=ST.length;
    while(low<=high){
        int mid=(low+high)/2;
        if(ST.elem[mid].key==key) return mid;
        else if(ST.elem[mid].key>key) high=mid-1;
        else low=mid+1;
    }
    return 0;
}

// 二叉排序树查找递归实现
BiTree SearchBST(BiTree T,KeyType key){
    if(!T || T->data.key==key) return T;
    if(key<T->data.key) return SearchBST(T->lchild,key);
    else return SearchBST(T->rchild,key);
}

// 除留余数哈希简单示例
#define HASH_LEN 101
int Hash(KeyType key){
    return key % HASH_LEN;
}

// BST查找递归实现
BiTree SearchBST(BiTree T, KeyType key){
    if(!T||T->data.key==key) return T;
    if(key<T->data.key)
        return SearchBST(T->lchild, key);
    else
        return SearchBST(T->rchild, key);
}

// 折半查找
int SearchBin(SSTable ST, KeyType key){
    int low=1, high=ST.length;
    while(low<=high){
        int mid=(low+high)/2;
        if(ST.elem[mid].key==key) return mid;
        else if(key<ST.elem[mid].key) high=mid-1;
        else low=mid+1;
    }
    return 0;
}

// 败者树多路归并核心逻辑伪代码
// b[]存放败者段编号，ls[]叶子节点对应k个归并段当前记录
void CreateLoserTree(int ls[],int b[],int k){
    for(int i=0;i<k;i++) b[k+i]=i;
    for(int i=k‑1;i>0;i--) Adjust(ls,b,i);
}
void Adjust(int ls[],int b[],int s){
    int t=(s+k)/2;
    while(t>0){
        if(ls[b[s]]>ls[b[t]]){ int tmp=b[s];b[s]=b[t];b[t]=tmp; s=t; }
        else break;
        t=t/2;
    }
}
